sys_script_include.script:
var NeedItUtils = Class.create();
NeedItUtils.prototype = {
    initialize: function() {
        // Create GlideDateTime object for the current date
        this.rightnow = new GlideDateTime();
    },
    isDatePast: function(strDate) {
        var testdate = new GlideDateTime(strDate);

        // If the testdate is before rightnow, return true, else return false
        if (testdate.before(this.rightnow)) {
            return true;
        } else {
            return false;
        }
    },
    isDateToday: function(strDate) {
        var testdate = new GlideDateTime(strDate);
		var whenNeededDate = testdate.getDate();
        var rightNowDate = this.rightnow.getDate();

		// If the testdate is rightnow, return true, else return false
        if (whenNeededDate.equals(rightNowDate)) {
            return true;
        } else {
            return false;
        }
    },
    type: 'NeedItUtils'
};
